using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using OpenAI;

// ── Bootstrap ───────────────────────────────────────────────────────────────
var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or configure AI:ApiKey.");

const string modelId = "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(pipeline => pipeline
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var host = builder.Build();
var chatClient = host.Services.GetRequiredService<IChatClient>();

// ── Tools ───────────────────────────────────────────────────────────────────
var notebook = new Notebook();
var webSearch = new WebSearchService();

var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearch.SearchAsync),
    AIFunctionFactory.Create(notebook.SaveNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// ── Agent ───────────────────────────────────────────────────────────────────
const string instructions = """
    You are a research agent. Your goal is to thoroughly research a topic the user provides.

    Follow this workflow:
    1. Break the topic into 2-3 specific search queries.
    2. Use the WebSearch tool to search for each query.
    3. Use the SaveNote tool to record the most important findings from each search.
    4. After gathering enough information, use the GetNotes tool to review all your notes.
    5. Provide a comprehensive summary with key findings, organized with clear headings.

    Always cite information sources. Be thorough but concise.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking tools.",
    tools: tools);

// ── Run ─────────────────────────────────────────────────────────────────────
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║      🔬  Research Agent  🔬         ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptUser();

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine(new string('─', 50));
Console.WriteLine();

var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var response = await agent.RunAsync(topic, session, runOptions);

Console.WriteLine();
Console.WriteLine(new string('═', 50));
Console.WriteLine("📋  RESEARCH SUMMARY");
Console.WriteLine(new string('═', 50));
Console.WriteLine(response.Text);
Console.WriteLine();

return;

static string PromptUser()
{
    Console.Write("Enter a topic to research: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrWhiteSpace(input)
        ? throw new InvalidOperationException("No topic provided.")
        : input;
}

// ── Notebook Tool ───────────────────────────────────────────────────────────
sealed class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Save a research note with key findings. Use this to record important information discovered during research.")]
    public string SaveNote(
        [Description("The note content to save")] string content,
        [Description("A short label for the note (e.g. 'overview', 'statistics')")] string label = "general")
    {
        _notes.Add($"[{label}] {content}");
        Console.WriteLine($"  📝 Note saved: \"{label}\" ({_notes.Count} total)");
        return $"Note '{label}' saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all previously saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"Note {i + 1}: {_notes[i]}");
        }

        return sb.ToString();
    }
}

// ── Web Search Tool ─────────────────────────────────────────────────────────
sealed partial class WebSearchService
{
    private readonly HttpClient _httpClient = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" }
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information. Returns a summary of search results for the given query.")]
    public async Task<string> SearchAsync(
        [Description("The search query")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo's instant answer API (no API key required)
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await _httpClient.GetStringAsync(url, cancellationToken);
            var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new StringBuilder();
            results.AppendLine($"Search results for: {query}");
            results.AppendLine();

            // Abstract (main answer)
            var abstractText = root.GetProperty("AbstractText").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.AppendLine($"Summary (from {abstractSource}): {abstractText}");
                results.AppendLine();
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var related))
            {
                var count = 0;
                foreach (var item in related.EnumerateArray())
                {
                    if (count >= 5) break;
                    var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.AppendLine($"- {text}");
                        count++;
                    }
                }
            }

            var result = results.ToString();

            if (result.Trim().Length < 50)
            {
                return $"Search for '{query}' returned limited results. Try rephrasing or using more specific terms.";
            }

            return result;
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try a different query.";
        }
    }
}

