    $"{nuget}/microsoft.extensions.ai.openai/10.7.0/lib/net10.0/",
    $"{nuget}/microsoft.extensions.ai.abstractions/10.7.0/lib/net10.0/",
    $"{nuget}/microsoft.extensions.ai/10.7.0/lib/net10.0/",
    $"{nuget}/openai/2.11.0/lib/net8.0/",
    $"{nuget}/system.clientmodel/1.4.0/lib/net8.0/",
};

var resolver = new PathAssemblyResolver(
    Directory.GetFiles(runtimeDir, "*.dll")
        .Concat(dirs.SelectMany(d => Directory.Exists(d) ? Directory.GetFiles(d, "*.dll") : []))
);

using var mlc = new MetadataLoadContext(resolver);
var asm = mlc.LoadFromAssemblyPath($"{nuget}/microsoft.extensions.ai.openai/10.7.0/lib/net10.0/Microsoft.Extensions.AI.OpenAI.dll");

// Find all public types and their public static methods (extension methods)
foreach (var t in asm.GetExportedTypes())
{
    var methods = t.GetMethods(BindingFlags.Public | BindingFlags.Static | BindingFlags.DeclaredOnly);
    if (methods.Length > 0)
    {
        Console.WriteLine($"\n{t.FullName}:");
        foreach (var m in methods)
        {
            var parms = string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
            Console.WriteLine($"  {m.ReturnType.Name} {m.Name}({parms})");
        }
    }
}
ENDOFCS

